const question = (code, choices, answer, explanation) => ({ code, choices, answer, explanation });
const example = (code, result, steps) => ({ code, result, steps });
const callbackParameters = (description) => [
  { name: "callbackFn", description: `${description} Receives the current item, its zero-based index, and the original array.` },
  { name: "thisArg (optional)", description: "Sets this inside a regular callback function. Arrow functions keep their surrounding this." },
];

