const javascriptOrder = ["map", "filter", "reduce", "forEach", "find", "some", "every", "sort", "includes", "keys", "values", "entries", "slice", "splice", "split", "findIndex", "push", "pop", "shift", "unshift", "replace", "trim", "toLowerCase", "toUpperCase", "substring"];
for (const lesson of lessons.javascript) {
  Object.assign(lesson, javascriptDetails[lesson.id] || {});
  lesson.mutates = lesson.mutates ?? false;
}
lessons.javascript.sort((a, b) => javascriptOrder.indexOf(a.id) - javascriptOrder.indexOf(b.id));

for (const language of Object.keys(lessons)) {
  for (const lesson of lessons[language]) {
    lesson.language = language;
    lesson.source = language === "javascript" ? jsDoc(lesson.id, lesson.inputType === "object" ? "Object" : lesson.inputType === "text" ? "String" : "Array") : pyDoc(["len", "sorted", "sum", "range"].includes(lesson.id) ? `functions.html#${lesson.id}` : `stdtypes.html#${lesson.id === "append" ? "typesseq-mutable" : lesson.id === "get" ? "dict.get" : `str.${lesson.id}`}`);
  }
}

export const defaultConfig = (lesson) => ({ input: lesson.input, operation: lesson.operation || "", parameter: lesson.parameter || "", extra: lesson.extra || "", additions: lesson.additions || "" });
